const fs=require('node:fs'),path=require('node:path');
const {JSDOM,VirtualConsole}=require('jsdom');
const {validateActionState}=require('./action-state.cjs');
let windows=[];
function fixture(){const html=fs.readFileSync(path.join(__dirname,'../index.html'),'utf8'),w=new JSDOM(html,{url:'http://localhost/',runScripts:'outside-only',virtualConsole:new VirtualConsole()}).window;windows.push(w);w.HTMLElement.prototype.checkVisibility=function(){return !this.hidden};w.eval(html.match(/<script>([\s\S]*?)<\/script>/)[1]+'\nwindow.checkBackup=validateImport;window.makeSeed=()=>({schema:1,...portableData(seed())});');const d=JSON.parse(JSON.stringify(w.makeSeed()));delete d.accounts;delete d.profiles;delete d.user;delete d.page;delete d.session;const links=[{label:'必需练习',url:'https://example.com/practice',affiliate:false,optional:false},{label:'可选工具',url:'https://example.com/tool',affiliate:true,optional:true}];const version=d.nodes.find(n=>n.methods.length).methods[0].versions[0];version.resource='';version.resourceLinks=structuredClone(links);d.events=[{id:'practice',name:'练习',startedAt:0,endedAt:1000,segments:[{start:0,end:1000}],steps:[],stepDone:{},draft:'',notes:[],knowledge:{nodeId:'eq',resourceLinks:structuredClone(links)}}];d.activeId=null;return {w,d,version}}
afterEach(()=>{windows.forEach(w=>w.close());windows=[]});
it('preserves all materials and flags across backup review and action-state validation',()=>{const {w,d}=fixture(),before=JSON.stringify(d);expect(w.checkBackup({format:'dianliang-local-backup/v1',data:d}).events[0].knowledge.resourceLinks).toEqual(d.events[0].knowledge.resourceLinks);expect(validateActionState(d)).toEqual(d);expect(JSON.stringify(d)).toBe(before)});
const bad=[['executable URL',r=>r.url='javascript:alert(1)'],['credential-bearing URL',r=>r.url='https://user:password@example.com/'],['unknown private field',r=>r.privateMemo='不得混入'],['missing boolean',r=>delete r.optional],['coerced boolean',r=>r.affiliate='false'],['empty label',r=>r.label='  '],['oversized label',r=>r.label='a'.repeat(81)],['oversized URL',r=>r.url='https://example.com/'+ 'a'.repeat(2001)]];
it.each(bad.flatMap(([label,change])=>['method','event'].map(location=>[label,location,change])))('rejects %s in %s without changing current data',(label,location,change)=>{const {w,d,version}=fixture();change((location==='method'?version.resourceLinks:d.events[0].knowledge.resourceLinks)[0]);const current=JSON.stringify(w.dianliangState),input=JSON.stringify(d);expect(()=>w.checkBackup({format:'dianliang-local-backup/v1',data:d})).toThrow();expect(()=>validateActionState(d)).toThrow();expect(JSON.stringify(w.dianliangState)).toBe(current);expect(JSON.stringify(d)).toBe(input)});
it.each(['method','event'])('rejects an oversized %s material list',location=>{const {w,d,version}=fixture(),links=location==='method'?version.resourceLinks:d.events[0].knowledge.resourceLinks;while(links.length<13)links.push({...links[0]});expect(()=>w.checkBackup({format:'dianliang-local-backup/v1',data:d})).toThrow();expect(()=>validateActionState(d)).toThrow()});
it('continues accepting legacy freeform material text without discarding it',()=>{const {w,d,version}=fixture();delete version.resourceLinks;version.resource='纸笔与自己的上一条笔记';delete d.events[0].knowledge.resourceLinks;expect(w.checkBackup({format:'dianliang-local-backup/v1',data:d}).nodes.find(n=>n.methods.length).methods[0].versions[0].resource).toBe(version.resource);expect(validateActionState(d)).toEqual(d)});
